#include <iostream>
#include <vector>
#include <cstdlib>
using namespace std;
int main() {
    int cases; cin >> cases;
    while (cases--) {
        int people; cin >> people;
        vector<int> addresses(people);
        int sum = 0;
        for (int i = 0; i < people; ++i) {
            cin >> addresses[i];
            sum += addresses[i];
        }
        int homePosition = sum / people;
        int total = 0;
        for (int i = 0; i < people; ++i) total += abs(addresses[i] - homePosition);
        cout << total << endl;
    }
    return 0;
}

